\fill[gray!25] (-4,0) arc (180:0:4) -- cycle;
\draw (-4,0)--(4,0);
\draw (-4,0) arc (180:0:4);
\draw (0,0)--(0,4) node[midway,left] {$4\text{ cm}$};
\fill (0,0) circle (2.5pt);
\end{tikzpicture}
[/tikz]
$A = \frac{1}{2}\pi r^{2}$
$= \frac{1}{2} \times \pi \times 4^{2}$
$= 8\pi\text{ cm}^{2}$
$V = Ah$
$= 8\pi \times 10$
$= 80\pi\text{ cm}^{3}$

